// O Clint envia: { clint_id, nome, telefone, email?, cpf?, origem?, utm_source?, utm_medium?, utm_campaign? }
const body = $input.item.json.body || $input.item.json;

// Normalizar telefone (remover +55, espaços, etc.)
const normalizarTelefone = (tel) => {
  if (!tel) return '';
  return tel.replace(/[^0-9]/g, '');
};

return {
  json: {
    clint_id:     body.clint_id || body.id,
    nome:         body.nome || body.name || '',
    telefone:     normalizarTelefone(body.telefone || body.phone || body.whatsapp || ''),
    email:        body.email || '',
    cpf:          (body.cpf || '').replace(/[^0-9]/g, ''),
    origem:       body.origem || body.source || 'whatsapp',
    utm_source:   body.utm_source || '',
    utm_medium:   body.utm_medium || '',
    utm_campaign: body.utm_campaign || ''
  }
};

